import{_ as t,o,c as a,a2 as i}from"./chunks/framework.CZo9GF0W.js";const g=JSON.parse('{"title":"06 — Roadmap: Phases & Milestones","description":"","frontmatter":{},"headers":[],"relativePath":"06-ROADMAP.md","filePath":"06-ROADMAP.md","lastUpdated":1789060268000}'),n={name:"06-ROADMAP.md"};function r(s,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="_06-—-roadmap-phases-milestones" tabindex="-1">06 — Roadmap: Phases &amp; Milestones <a class="header-anchor" href="#_06-—-roadmap-phases-milestones" aria-label="Permalink to &quot;06 — Roadmap: Phases &amp; Milestones&quot;">​</a></h1><p>Estimates assume <strong>one full-time developer</strong>. Two devs → roughly parallelize Phases 3+4 and 6+7.</p><table tabindex="0"><thead><tr><th>Phase</th><th>Title</th><th>Est.</th><th>Cumulative</th></tr></thead><tbody><tr><td>0</td><td>Foundations</td><td>1 wk</td><td>1</td></tr><tr><td>1</td><td>Connections + Explorer</td><td>3 wk</td><td>4</td></tr><tr><td>2</td><td>Query mode MVP</td><td>3 wk</td><td>7</td></tr><tr><td>3</td><td>UI mode — data view &amp; editing</td><td>4 wk</td><td>11</td></tr><tr><td>4</td><td>SQL intelligence</td><td>3 wk</td><td>14</td></tr><tr><td>5</td><td>Productivity (history, export, notebooks)</td><td>3 wk</td><td>17</td></tr><tr><td>6</td><td>Postgres power features</td><td>4 wk</td><td>21</td></tr><tr><td>7</td><td>ERD + schema tooling</td><td>4 wk</td><td>25</td></tr><tr><td>8</td><td>Performance &amp; scale hardening</td><td>3 wk</td><td>28</td></tr><tr><td>9</td><td>Second driver (SQLite)</td><td>2 wk</td><td>30</td></tr><tr><td>10</td><td>Packaging &amp; release</td><td>2 wk</td><td>32</td></tr><tr><td>11</td><td>Multi-model contract generalization</td><td>3 wk</td><td>35</td></tr><tr><td>12</td><td>MongoDB driver</td><td>4 wk</td><td>39</td></tr><tr><td>13</td><td>Redis driver</td><td>3 wk</td><td>42</td></tr><tr><td>14</td><td>MySQL / MariaDB driver</td><td>2 wk</td><td>44</td></tr><tr><td>15</td><td>SQL Server driver</td><td>2 wk</td><td>46</td></tr></tbody></table><p><strong>Milestones</strong></p><ul><li><strong>M1 — Internal alpha</strong> (end of Phase 2): connect, browse, run SQL, see results. Dogfoodable.</li><li><strong>M2 — Public beta</strong> (end of Phase 5): both modes complete, published as pre-release on Marketplace + Open VSX.</li><li><strong>M3 — v1.0</strong> (end of Phase 8 + 10): Postgres feature-complete, perf budgets met, docs done.</li><li><strong>M4 — v1.1</strong> (end of Phase 9): multi-driver proven against a second relational engine.</li><li><strong>M5 — v1.2, multi-model</strong> (end of Phase 13): MongoDB and Redis ship from the same core. The claim on the tin changes from &quot;PostgreSQL client with a driver layer&quot; to &quot;one client, several kinds of database&quot;.</li><li><strong>M6 — v1.3</strong> (end of Phase 14): MySQL/MariaDB, and the driver-authoring guide proven by someone outside the project using it.</li><li><strong>M7 — v1.4</strong> (end of Phase 15): SQL Server, which completes the four relational engines most teams actually run.</li></ul><p>Phases 6/7 can slip past v1.0 without blocking it — Phase 8 and 10 are the true v1.0 gates. Phase 9 is deliberately <em>after</em> v1.0: the registry&#39;s design is validated by real use before a second engine locks it in.</p><p>Phases 11–14 are all post-v1.0 and none of them gate it. Phase 11 ships no user-visible feature and is still not optional: it is the contract work MongoDB and Redis both need, done once and reviewed on its own terms rather than smuggled into a driver PR (ADR-034).</p><hr><h2 id="phase-0-—-foundations-·-1-wk" tabindex="-1">Phase 0 — Foundations · 1 wk <a class="header-anchor" href="#phase-0-—-foundations-·-1-wk" aria-label="Permalink to &quot;Phase 0 — Foundations · 1 wk&quot;">​</a></h2><p><strong>Goal:</strong> an empty extension that installs, activates, runs a &quot;Hello&quot; command, and has CI green.</p><ul><li>pnpm workspace, TS 5 strict, packages per Architecture §2.</li><li>esbuild bundle for the extension, Vite for <code>webview-ui</code>, watch tasks, <code>.vscode/launch.json</code> for F5 debugging.</li><li>eslint + <code>dependency-cruiser</code> boundary rules (core must not import <code>vscode</code>/<code>pg</code>) wired into CI.</li><li>Vitest for unit, <code>@vscode/test-electron</code> harness stub.</li><li>GitHub Actions: lint · typecheck · unit · package VSIX artifact.</li><li><code>docker-compose.test.yml</code> with PG 13 / 15 / 17 for later integration tests.</li><li>Output channel + leveled logger with the redaction pass (S1.4) — built now, so nothing ever logs a secret.</li></ul><p><strong>Exit:</strong> <code>pnpm package</code> produces an installable VSIX; CI green on a clean clone.</p><hr><h2 id="phase-1-—-connections-explorer-·-3-wk" tabindex="-1">Phase 1 — Connections + Explorer · 3 wk <a class="header-anchor" href="#phase-1-—-connections-explorer-·-3-wk" aria-label="Permalink to &quot;Phase 1 — Connections + Explorer · 3 wk&quot;">​</a></h2><p><strong>Goal:</strong> add a Postgres connection, see its objects.</p><ul><li><code>DriverAdapter</code>/<code>Session</code> interfaces + registry (<code>03-DRIVER-API.md</code>).</li><li><code>driver-pg</code>: node-postgres, pool, TLS, <code>ssh2</code> tunnel, cancel-request, server-version detection.</li><li>Secrets: SecretStorage wiring, <code>SecretRef</code> resolution (keychain, env, <code>.pgpass</code>, <code>pg_service.conf</code>, prompt).</li><li>Connection form webview, schema-driven from <code>connectionSchema</code>; URI paste parser; Test Connection.</li><li>Profile stores: global + workspace file, JSON Schema published, secret-literal rejection (S1.2).</li><li>Environment tagging, color, read-only flag, guard scaffolding.</li><li>Explorer TreeDataProvider: lazy children, virtualized, filter box, refresh, context menus.</li><li><code>IntrospectionPlan</code> for PG: databases, schemas, tables, views, matviews, functions, types, sequences, extensions; version-gated catalog SQL for PG 13→17.</li><li>Metadata cache with TTL + eager invalidation.</li></ul><p><strong>Exit:</strong> connect over TLS and over an SSH tunnel; expand a 5 000-table schema in &lt; 1 s; no secret on disk (verified by a test that greps the whole storage dir).</p><hr><h2 id="phase-2-—-query-mode-mvp-·-3-wk" tabindex="-1">Phase 2 — Query mode MVP · 3 wk <a class="header-anchor" href="#phase-2-—-query-mode-mvp-·-3-wk" aria-label="Permalink to &quot;Phase 2 — Query mode MVP · 3 wk&quot;">​</a></h2><p><strong>Goal:</strong> write SQL, run it, read the results. <strong>M1.</strong></p><ul><li>Editor↔connection binding: status bar picker, per-file persistence, <code>-- @pitta connection:</code> directive.</li><li>Statement splitter handling dollar-quoting, <code>E&#39;&#39;</code>, nested comments, <code>\\</code> meta-commands.</li><li>CodeLens <code>▶ Run · Explain</code>; keybindings for run-statement / run-selection / run-all / cancel.</li><li>Execution engine: multi-statement → tabbed results, timing, <code>commandTag</code>, live elapsed, real cancel.</li><li>Results webview v1: TanStack virtualized grid, columnar store, type-aware renderers, <code>NULL</code> token, exact <code>numeric</code>.</li><li>Messages tab streaming <code>NOTICE</code>/<code>RAISE</code>.</li><li>Copy as TSV/CSV/JSON/Markdown/INSERT.</li><li>Guards live: destructive confirm, unqualified-DML block, read-only enforcement.</li><li>Errors surfaced with <code>SQLSTATE</code>, position → squiggle mapped back into the editor.</li></ul><p><strong>Exit (M1):</strong> run a 200-column × 100k-row query; results usable; cancel actually stops the server-side query (verified against <code>pg_stat_activity</code>).</p><hr><h2 id="phase-3-—-ui-mode-data-view-editing-·-4-wk" tabindex="-1">Phase 3 — UI mode: data view &amp; editing · 4 wk <a class="header-anchor" href="#phase-3-—-ui-mode-data-view-editing-·-4-wk" aria-label="Permalink to &quot;Phase 3 — UI mode: data view &amp; editing · 4 wk&quot;">​</a></h2><p><strong>Goal:</strong> never type SQL to look at or fix a row.</p><ul><li>Table Data panel: keyset paging, <code>LIMIT/OFFSET</code> fallback, generated-SQL always visible.</li><li>Filter row with per-type operators; multi-column sort; column show/hide/pin/reorder/resize persisted.</li><li>Cell editors per type: text, exact-decimal number, tri-state boolean, date/time w/ timezone, enum dropdown, JSON editor w/ validation, array chips, bytea up/download, FK picker.</li><li>Staged-edit model, dirty highlighting, DML preview diff, single-transaction apply, rollback on any error, affected-row-count verification.</li><li>Insert / duplicate / delete row.</li><li>PK/unique detection; <code>ctid</code> opt-in fallback; clear disabled reason when neither exists.</li><li>Structure panel: Columns · Indexes · Constraints · Triggers · Policies · Partitions · Statistics · DDL.</li><li><code>generateDdl</code> for tables/views/functions/types/sequences, round-trip tested against <code>pg_dump</code>.</li></ul><p><strong>Exit:</strong> edit 20 cells across 5 rows including a jsonb and an enum, apply as one transaction, verified in psql. Editing a view or PK-less table degrades gracefully with a readable reason.</p><hr><h2 id="phase-4-—-sql-intelligence-·-3-wk-—-done" tabindex="-1">Phase 4 — SQL intelligence · 3 wk — <strong>done</strong> <a class="header-anchor" href="#phase-4-—-sql-intelligence-·-3-wk-—-done" aria-label="Permalink to &quot;Phase 4 — SQL intelligence · 3 wk — **done**&quot;">​</a></h2><ul><li><code>@pgsql/parser</code> WASM integration (the maintained WASM build of libpg-query; ADR-026) → real Postgres grammar for syntax diagnostics + the statement analyzer used by guards (replaces Phase 2&#39;s heuristic splitter internals).</li><li>Completion: alias-aware columns, <code>FROM</code>-driven scope, functions with signatures, enum values in comparisons, keyword ranking. Served from the metadata cache.</li><li>Hover: types, defaults, nullability, comments, table size/row estimate.</li><li>Go-to-definition → DDL virtual document; find-references across open <code>.sql</code> files.</li><li>Semantic diagnostics: unknown table/column, ambiguous column, obvious type mismatch.</li><li>Formatter + format-on-save; snippets; user templates.</li></ul><p><strong>Exit:</strong> met. Completion p95 <strong>1.2 ms</strong> on a 2 000-relation / 40 000-column fixture against a 50 ms budget; syntax diagnostics come from the server&#39;s own grammar rather than a corpus-matched heuristic, which is a stronger result than the acceptance test asked for.</p><hr><h2 id="phase-5-—-productivity-·-3-wk-m2-—-public-beta-—-done-except-publishing" tabindex="-1">Phase 5 — Productivity · 3 wk. <strong>M2 — public beta.</strong> — <strong>done, except publishing</strong> <a class="header-anchor" href="#phase-5-—-productivity-·-3-wk-m2-—-public-beta-—-done-except-publishing" aria-label="Permalink to &quot;Phase 5 — Productivity · 3 wk. **M2 — public beta.** — **done, except publishing**&quot;">​</a></h2><ul><li>Query history: JSONL store, search, filter by connection/status, re-run, prod exclusion.</li><li>Saved queries as plain <code>.sql</code> in a workspace folder; tree view; parameter prompts (<code>:name</code> / <code>$1</code>) sent as binds.</li><li>Export: CSV / JSON / JSONL / XLSX / SQL inserts — <strong>streamed to disk</strong>, progress + cancel, never fully materialized.</li><li>Import: CSV → table with column mapping, type coercion preview, <code>COPY</code> fast path.</li><li>SQL Notebooks (<code>.pittabook</code>): serializer, controller, per-<em>notebook</em> connection (ADR-029), HTML/JSON/markdown outputs, export to <code>.sql</code>.</li><li>Onboarding walkthrough (<code>contributes.walkthroughs</code>), README, docs site skeleton.</li></ul><p><strong>Exit (M2):</strong> export budget met in Phase 8&#39;s benchmarks. The publish pipeline is built and the VSIX is verified in CI, but <strong>nothing has been published</strong>: that needs a publisher account and the two tokens, which is a decision to make rather than a task to finish.</p><hr><h2 id="phase-6-—-postgres-power-features-·-4-wk-—-done" tabindex="-1">Phase 6 — Postgres power features · 4 wk — <strong>done</strong> <a class="header-anchor" href="#phase-6-—-postgres-power-features-·-4-wk-—-done" aria-label="Permalink to &quot;Phase 6 — Postgres power features · 4 wk — **done**&quot;">​</a></h2><ul><li>EXPLAIN visualizer: <code>FORMAT JSON</code> → interactive tree, cost/time/rows, skew and seq-scan red flags, plan diff.</li><li>Session monitor (<code>pg_stat_activity</code>): live table, blocking chain, cancel/terminate backend (guarded).</li><li>Lock inspector (<code>pg_locks</code>).</li><li>LISTEN/NOTIFY subscriber panel.</li><li>Health advisor: unused/duplicate indexes, missing FK indexes, bloat estimate, seq-scan-heavy tables, autovacuum lag — read-only report + suggested DDL.</li><li>Extensions panel; roles/privileges browser; publications/subscriptions/replication-slot listing.</li><li>pgvector + PostGIS cell awareness.</li></ul><p><strong>Exit:</strong> plan visualizer renders a 60-node plan legibly and flags a known-bad estimate skew on a fixture query.</p><hr><h2 id="phase-7-—-erd-schema-tooling-·-4-wk" tabindex="-1">Phase 7 — ERD + schema tooling · 4 wk <a class="header-anchor" href="#phase-7-—-erd-schema-tooling-·-4-wk" aria-label="Permalink to &quot;Phase 7 — ERD + schema tooling · 4 wk&quot;">​</a></h2><ul><li>ERD canvas: dagre auto-layout, FK edges, drag + persist layout, filter to neighbors, PNG/SVG export, click-through to Structure.</li><li>Schema diff between two connections/schemas → generated migration SQL, reviewed before execution anywhere.</li><li>Migration file export (plain SQL / Flyway naming).</li><li><strong>[P2]</strong> Visual table designer emitting reviewable <code>ALTER TABLE</code>.</li></ul><p><strong>Exit:</strong> diff two 300-table schemas in &lt; 5 s; generated migration applies cleanly against the target and re-diffs to empty.</p><hr><h2 id="phase-8-—-performance-scale-hardening-·-3-wk-v1-0-gate-—-done" tabindex="-1">Phase 8 — Performance &amp; scale hardening · 3 wk (<strong>v1.0 gate</strong>) — <strong>done</strong> <a class="header-anchor" href="#phase-8-—-performance-scale-hardening-·-3-wk-v1-0-gate-—-done" aria-label="Permalink to &quot;Phase 8 — Performance &amp; scale hardening · 3 wk (**v1.0 gate**) — **done**&quot;">​</a></h2><ul><li>Optional forked <code>QueryHost</code> child process per connection group; driver + serialization move off the extension host.</li><li>Columnar store tuning: typed arrays, string interning, LRU eviction against <code>pitta.gridCacheBudgetMB</code>.</li><li>Cursor streaming end-to-end; backpressure so a fast server can&#39;t outrun the webview.</li><li>Benchmark suite in CI with hard budgets: 1M×20 stream &lt; 600 MB RSS · first page &lt; 500 ms · scroll ≥ 50 fps · activation &lt; 200 ms · tree expand on 10k objects &lt; 1 s.</li><li>Memory-leak soak: open/close 200 panels, run 1 000 queries, assert flat heap.</li><li>Cold-start audit: lazy <code>activationEvents</code>, defer driver import until first connect.</li></ul><p><strong>Exit:</strong> every budget met in CI on the smallest runner tier; regressions fail the build.</p><hr><h2 id="phase-9-—-second-driver-sqlite-·-2-wk" tabindex="-1">Phase 9 — Second driver (SQLite) · 2 wk <a class="header-anchor" href="#phase-9-—-second-driver-sqlite-·-2-wk" aria-label="Permalink to &quot;Phase 9 — Second driver (SQLite) · 2 wk&quot;">​</a></h2><ul><li><code>packages/driver-sqlite</code> implementing the full contract; passes the conformance kit.</li><li><strong>Hard rule:</strong> the PR touches only <code>packages/driver-sqlite</code>, the registry map, and docs. Any change forced in <code>core</code>/<code>extension</code> is a design defect — fix the abstraction, then re-land.</li><li>Capability-flag gaps exercised for real (no schemas, no cursors, no LISTEN/NOTIFY) — proves the UI gating works.</li></ul><p><strong>Exit:</strong> SQLite connection browses, queries, and edits with zero core diffs. Then MySQL becomes a tractable community contribution.</p><hr><h2 id="phase-10-—-packaging-release-·-2-wk" tabindex="-1">Phase 10 — Packaging &amp; release · 2 wk <a class="header-anchor" href="#phase-10-—-packaging-release-·-2-wk" aria-label="Permalink to &quot;Phase 10 — Packaging &amp; release · 2 wk&quot;">​</a></h2><ul><li>Marketplace + Open VSX listings, icon, animated README demos, category/keyword tuning.</li><li>Docs site (VitePress) — getting started, connection recipes (Docker, RDS, Cloud SQL, Supabase, Neon, SSH), troubleshooting, driver-authoring guide.</li><li><strong>Remote-SSH/WSL/devcontainer doc</strong>: connections originate on the <em>remote</em> host — the single most common user confusion.</li><li>Telemetry opt-in flow + documented event list.</li><li>Issue templates, <code>CONTRIBUTING.md</code>, license (MIT), security policy + disclosure address.</li><li>Release automation: semantic-release, changelog, signed VSIX, pre-release channel.</li></ul><p><strong>Exit:</strong> clean-machine install → connected and querying in under 30 s, guided only by the README.</p><hr><h2 id="phase-11-—-multi-model-contract-generalization-·-3-wk" tabindex="-1">Phase 11 — Multi-model contract generalization · 3 wk <a class="header-anchor" href="#phase-11-—-multi-model-contract-generalization-·-3-wk" aria-label="Permalink to &quot;Phase 11 — Multi-model contract generalization · 3 wk&quot;">​</a></h2><p><strong>Goal:</strong> the contract stops assuming SQL. No new engine ships; PostgreSQL and SQLite behave exactly as before. Full detail in <code>10-ENGINE-MODEL.md</code>, rationale in ADR-034.</p><ul><li><code>EngineLanguage</code> on the adapter; <code>Statement.sql</code> → <code>Statement.text</code>; every &quot;SQL&quot; in a UI string reads the language&#39;s display name.</li><li><code>splitStatements</code> / <code>formatCommand</code> / <code>classifyCommand</code> become driver methods with the current SQL implementations moving to <code>driver-pg</code>, and the shared heuristic staying in core as the floor (ADR-027&#39;s combining rule intact).</li><li>Imperative, paged introspection: <code>NodeDefinition.fetch</code>, tree <code>Load more</code>, <code>pitta.explorer.treePageSize</code>.</li><li>Open <code>ObjectKind</code> + <code>NodeKindDescriptor</code>; explorer icons and context menus read descriptors instead of a switch.</li><li><code>ResultShape</code>; <code>documents</code> projection; <code>message</code> results render as messages.</li><li>Missing-vs-null: wire cell gains <code>{ missing: true }</code>, grid token, <code>exists</code> / <code>notExists</code> / <code>regex</code> filter ops, <code>$unset</code>-style clear-vs-remove editing.</li><li>Cursor page mode end to end: <code>GridQuery.page</code>, <code>QueryHandle.nextCursor</code>, grid page control degrades to Next/Previous when offsets are unavailable.</li><li>Capability additions per <code>10 §8</code>, session-level capability overlay per ADR-035.</li><li><code>supportsAtomicEdits: false</code> apply path: honest dialog wording, per-edit applied/not-applied reporting.</li><li>Conformance kit becomes engine-agnostic (<code>EngineFixture</code>); PG and SQLite re-pass it unchanged.</li><li>Query mode, saved queries, history and notebooks become language-generic.</li></ul><p><strong>Exit:</strong> PG and SQLite pass the rewritten conformance kit with no behavior change, the benchmark suite shows no regression, and a throwaway &quot;echo driver&quot; with a non-SQL language, imperative introspection, document results and no transactions browses and edits end to end without a core edit. That last one is the actual test of whether this phase worked.</p><hr><h2 id="phase-12-—-mongodb-driver-·-4-wk" tabindex="-1">Phase 12 — MongoDB driver · 4 wk <a class="header-anchor" href="#phase-12-—-mongodb-driver-·-4-wk" aria-label="Permalink to &quot;Phase 12 — MongoDB driver · 4 wk&quot;">​</a></h2><p><strong>Goal:</strong> browse, query, edit and monitor MongoDB from the same UI. Detail in <code>11-ENGINE-MONGODB.md</code>.</p><ul><li><code>packages/driver-mongodb</code> on the pure-JS <code>mongodb</code> driver (ADR-046): connect (standalone / replica set / sharded / Atlas SRV), TLS, SCRAM / x509 / AWS IAM, SSH tunnel reuse, topology probe → session capabilities.</li><li>Tree: databases, collections, views, indexes, inferred fields, server info.</li><li><code>.mongodb.js</code> language: acorn parse → allowlisted call shapes → BSON, never evaluated (ADR-042); splitting, completion from the sampled schema, hover, diagnostics.</li><li>Cursor-backed streaming results; cancel via labelled operation + <code>killOp</code> (ADR-043).</li><li>Document grid: sampled column union, BSON type mapping with Decimal128 and Int64 exact, missing token, detail pane.</li><li>Editing: <code>updateOne</code>/<code>insertOne</code>/<code>deleteOne</code> preview, <code>$set</code> vs <code>$unset</code>, nested and positional paths, transactional apply where the topology allows.</li><li>Structure sections: fields (inferred), indexes, validation, sharding, stats.</li><li><code>explain</code> → the existing plan visualizer, with Mongo-specific red-flag rules.</li><li><code>$currentOp</code> monitor + <code>killOp</code>; health report from <code>$indexStats</code>, <code>serverStatus</code>, <code>dbStats</code>.</li><li>Import (CSV / JSON / NDJSON via <code>insertMany</code> batches), export (JSON, EJSON, NDJSON, CSV with a stated flattening rule).</li><li>Guards: empty-filter <code>deleteMany</code>/<code>updateMany</code>, <code>drop*</code>, <code>$out</code>/<code>$merge</code> detection, server-side JS off by default.</li></ul><p><strong>Exit:</strong> against a seeded replica set — browse 500 collections, run a <code>find</code> and an <code>aggregate</code>, edit a nested field and an array element and verify in <code>mongosh</code>, cancel a slow aggregation and see the op gone from <code>$currentOp</code>, and stream a 1M-document collection inside the existing memory budget.</p><hr><h2 id="phase-13-—-redis-driver-·-3-wk" tabindex="-1">Phase 13 — Redis driver · 3 wk <a class="header-anchor" href="#phase-13-—-redis-driver-·-3-wk" aria-label="Permalink to &quot;Phase 13 — Redis driver · 3 wk&quot;">​</a></h2><p><strong>Goal:</strong> a Redis client that is safe to point at production. Detail in <code>12-ENGINE-REDIS.md</code>.</p><ul><li><code>packages/driver-redis</code> on <code>ioredis</code>: standalone / sentinel / cluster, ACL auth, TLS, SSH tunnel reuse, <code>CLIENT SETNAME</code>, <code>COMMAND INFO</code> table read at connect.</li><li>Keyspace tree: databases from <code>DBSIZE</code>/<code>INFO keyspace</code>, SCAN-based prefix folders from a bounded sample, cursor paging, never <code>KEYS</code> (ADR-044).</li><li>Per-type value views: string, hash, list, set, zset, stream (+ consumer groups), JSON module. TTL as a first-class, editable field.</li><li><code>.redis</code> command language: redis-cli-compatible splitting and quoting, completion and hover from <code>COMMAND DOCS</code>, reply-shaped results.</li><li>Editing through <code>buildEdits</code> with a previewed command list, <code>MULTI</code>/<code>EXEC</code> where slots allow, and honest no-rollback wording (ADR-041).</li><li>Pub/Sub panel (generalized P6-T6) including keyspace notifications; <code>MONITOR</code> opt-in, time-boxed, refused on prod.</li><li><code>CLIENT LIST</code> monitor + <code>CLIENT KILL</code>; health from <code>INFO</code>, <code>SLOWLOG</code>, <code>MEMORY</code>, plus an opt-in sampled big-key and TTL-coverage report.</li><li>Guards from the server&#39;s own command flags, unknown fails closed on prod.</li></ul><p><strong>Exit (M5):</strong> against a 1M-key instance — expand the tree without the server noticing (verified with <code>SLOWLOG</code> and <code>INFO commandstats</code>: no <code>KEYS</code>, no command above the latency budget), read and edit each key type, set and clear a TTL, and have <code>FLUSHALL</code> on a prod-tagged profile demand the typed confirmation. Plus the same run against a three-node cluster.</p><hr><h2 id="phase-14-—-mysql-mariadb-driver-·-2-wk" tabindex="-1">Phase 14 — MySQL / MariaDB driver · 2 wk <a class="header-anchor" href="#phase-14-—-mysql-mariadb-driver-·-2-wk" aria-label="Permalink to &quot;Phase 14 — MySQL / MariaDB driver · 2 wk&quot;">​</a></h2><p><strong>Goal:</strong> the largest remaining audience, and the test of whether someone outside the project can write a driver from the guide.</p><ul><li><code>packages/driver-mysql</code> on <code>mysql2</code> (pure JS): connect, TLS, SSH tunnel, <code>KILL QUERY</code> cancel, <code>information_schema</code> introspection, type mapping with <code>DECIMAL</code> and <code>BIGINT</code> exact, backtick quoting, <code>?</code> placeholders.</li><li><code>EXPLAIN FORMAT=JSON</code> and <code>EXPLAIN ANALYZE</code> into the existing plan model.</li><li><code>SHOW PROCESSLIST</code> monitor, <code>performance_schema</code> health report, <code>LOAD DATA LOCAL INFILE</code> bulk path, <code>SHOW CREATE</code> DDL generation.</li><li>Written <strong>against the driver-authoring guide</strong> (P10-T2), with every gap in the guide filed as a doc bug rather than worked around.</li></ul><p><strong>Exit (M6):</strong> conformance kit green against MySQL 8 and MariaDB 11 in CI, and the guide updated with whatever writing this driver revealed.</p><hr><h2 id="phase-15-—-sql-server-driver-·-2-wk" tabindex="-1">Phase 15 — SQL Server driver · 2 wk <a class="header-anchor" href="#phase-15-—-sql-server-driver-·-2-wk" aria-label="Permalink to &quot;Phase 15 — SQL Server driver · 2 wk&quot;">​</a></h2><p><strong>Goal:</strong> the last of the four relational engines most teams run, and the first one whose client protocol argues with the contract rather than fitting it.</p><ul><li><code>packages/driver-mssql</code> on <code>mssql</code>/<code>tedious</code> (pure JS): connect, TLS in SQL Server&#39;s own two-switch vocabulary, SSH tunnel, NTLM for a domain login, attention-packet cancel, <code>sys</code> catalog introspection with three-part names, bracket quoting, <code>@1</code> placeholders.</li><li><code>SHOWPLAN_ALL</code> and <code>STATISTICS PROFILE</code> into the existing plan model, through a pinned batch, plus SQL Server&#39;s own red flags: a scan judged against the table&#39;s real size, a key lookup that ran too often, an estimate far from the actual, an implicit conversion, and the server&#39;s own operator warnings.</li><li><code>sys.dm_exec_*</code> session monitor, DMV health report (missing and unread indexes, page life expectancy, log space), <code>sys.sql_modules</code> DDL for anything with a body and a composed <code>CREATE TABLE</code> for anything without one.</li><li>Exact numerics converted on the server, because TDS cannot carry them (ADR-058) - the one place an engine&#39;s protocol made ADR-004 a fight.</li></ul><p><strong>Exit (M7):</strong> conformance kit and integration suite green against SQL Server 2022 in docker, including that DDL inside a transaction really rolls back and that a wide <code>decimal</code> read through the grid is exact.</p>',80)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
